package com.ruoyi.paicli.service;

import com.ruoyi.paicli.domain.*;
import tools.jackson.core.*;
import tools.jackson.core.json.JsonFactory;
import tools.jackson.databind.ObjectMapper;
import java.io.*;
import java.nio.file.Files;
import java.util.*;

/** 大型控制结果只流式提取正式目录字段，不展开巨型result或完整128MiB事件树。 */
public final class PcCatalogueArtifact {
    private static final long FIELD_LIMIT=16L*1024*1024,DOCUMENT_LIMIT=128L*1024*1024;
    private static final Set<String> FIELDS=Set.of("tools","resources","prompts");
    private final PcStore store;private final PcArtifactService artifacts;
    public PcCatalogueArtifact(PcStore store,PcArtifactService artifacts){this.store=store;this.artifacts=artifacts;}
    public Map<String,Object> read(PcRecord task,Map<String,Object> projection){Map<String,Object> digests=PcJson.object(projection,"catalogueDigests");if(digests.isEmpty()||!FIELDS.containsAll(digests.keySet()))throw PcException.invalid("目录digest仅允许实际tools/resources/prompts");long id=PcJson.number(projection,"eventArtifactId");Map<String,Object> metadata=artifacts.runnerOutputMetadata(id,task.getWorkspaceId(),task.getOwnerId(),task.getSessionId());if(!String.valueOf(task.getId()).equals(metadata.get("parentId"))||!Objects.equals(metadata.get("sha256"),projection.get("eventArtifactSha256"))||PcJson.number(metadata,"size")!=PcJson.number(projection,"eventArtifactSize"))throw PcException.deny("目录产物不是当前任务完整结果");var content=artifacts.content(task.getOwnerId(),id);Map<String,Object> envelope=new LinkedHashMap<>(),payload=new LinkedHashMap<>();ObjectMapper parserMapper=new ObjectMapper(JsonFactory.builder().streamReadConstraints(StreamReadConstraints.builder().maxDocumentLength(DOCUMENT_LIMIT).maxStringLength((int)DOCUMENT_LIMIT).build()).build()).rebuild().disable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
        validateConsumedControl(task,metadata);
        try(var input=new LimitedInput(Files.newInputStream(content.file()));var parser=parserMapper.createParser(input)){if(parser.nextToken()!=JsonToken.START_OBJECT)throw PcException.invalid("目录产物须为完整事件对象");Set<String> names=new HashSet<>();while(parser.nextToken()!=JsonToken.END_OBJECT){if(parser.currentToken()!=JsonToken.PROPERTY_NAME)throw PcException.invalid("事件产物字段非法");String name=parser.currentName();if(!names.add(name))throw PcException.invalid("事件产物字段重复");parser.nextToken();if(name.equals("payload")){readPayload(parser,parserMapper,input,payload,digests);}else if(Set.of("taskId","sessionId","type").contains(name)){envelope.put(name,scalar(parser,input));}else parser.skipChildren();}if(parser.nextToken()!=null)throw PcException.invalid("事件产物包含尾随内容");if(input.consumed!=content.size()||!input.sha256().equals(content.sha256()))throw PcException.conflict("目录产物流式读取期间SHA或长度改变");}catch(PcException invalid){throw invalid;}catch(Exception invalid){throw new PcException(422,"PC_CATALOGUE_ARTIFACT","目录产物JSON或容量核验失败，未登记部分目录");}
        if(!String.valueOf(task.getId()).equals(envelope.get("taskId"))||!String.valueOf(task.getSessionId()).equals(envelope.get("sessionId"))||!"CONNECTION_RESULT".equals(envelope.get("type")))throw PcException.deny("目录产物envelope不属于当前任务/会话");for(String field:List.of("kind","configId","configVersion","status"))if(!Objects.toString(projection.get(field),"").equals(Objects.toString(payload.get(field),"")))throw PcException.conflict("目录产物配置scope或版本与projection不同");Map<String,Object> result=new LinkedHashMap<>();for(String field:digests.keySet()){if(!payload.containsKey(field))throw PcException.invalid("目录产物缺少声明字段："+field);result.put(field,payload.get(field));}return result;
    }
    private void readPayload(JsonParser parser,ObjectMapper mapper,LimitedInput input,Map<String,Object> payload,Map<String,Object> digests)throws IOException{if(parser.currentToken()!=JsonToken.START_OBJECT)throw PcException.invalid("目录产物payload不是对象");Set<String> names=new HashSet<>();while(parser.nextToken()!=JsonToken.END_OBJECT){if(parser.currentToken()!=JsonToken.PROPERTY_NAME)throw PcException.invalid("目录payload字段非法");String field=parser.currentName();if(!names.add(field))throw PcException.invalid("目录payload字段重复");parser.nextToken();if(digests.containsKey(field)){if(parser.currentToken()!=JsonToken.START_ARRAY)throw PcException.invalid("正式目录字段须为完整数组");Map<String,Object> digest=PcJson.object(digests,field);long declared=PcJson.number(digest,"size");if(declared<2||declared>FIELD_LIMIT||!PcJson.text(digest,"sha256").matches("[a-f0-9]{64}"))throw PcException.invalid("目录字段digest/容量非法");input.limit(parser.currentTokenLocation().getByteOffset()+FIELD_LIMIT+16384);List<Object> values=new ArrayList<>();while(parser.nextToken()!=JsonToken.END_ARRAY){if(parser.currentToken()!=JsonToken.START_OBJECT)throw PcException.invalid("目录数组每项须为对象");values.add(mapper.readValue(parser,Object.class));}input.limit(DOCUMENT_LIMIT);String canonical=store.json.write(values);long size=canonical.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(size>FIELD_LIMIT||size!=declared||!PcJson.digest(canonical).equals(digest.get("sha256")))throw PcException.conflict("完整目录数组与声明SHA/容量不一致");payload.put(field,values);}else if(Set.of("kind","configId","configVersion","status").contains(field)){payload.put(field,scalar(parser,input));}else parser.skipChildren();}}
    private static String scalar(JsonParser parser,LimitedInput input){if(!parser.currentToken().isScalarValue()||parser.currentToken()==JsonToken.VALUE_NULL)throw PcException.invalid("目录归属字段须为非空标量");input.limit(parser.currentTokenLocation().getByteOffset()+16384+1024);String value=parser.getValueAsString();input.limit(DOCUMENT_LIMIT);if(value==null||value.length()>256)throw PcException.invalid("目录归属字段超限");return value;}
    private void validateConsumedControl(PcRecord task,Map<String,Object> metadata){
        String callId=PcJson.text(metadata,"toolCallId");PcRecord call=store.mapper.findKey(PcTable.TOOL_CALL,"task:"+task.getId()+":call:"+callId,false),lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),false);
        if(call==null||lease==null||!"CONSUMED".equals(call.getState())||!call.getKind().equals("control__"+PcJson.text(store.data(task),"operation"))||!Objects.equals(call.getOwnerId(),task.getOwnerId())||!Objects.equals(call.getWorkspaceId(),task.getWorkspaceId())||!Objects.equals(call.getSessionId(),task.getSessionId()))throw PcException.deny("目录产物没有当前控制动作已消费的许可");Map<String,Object> binding=store.data(call);if(PcJson.number(binding,"leaseId")!=lease.getId()||PcJson.number(binding,"fencingToken")!=lease.getFencingToken()||lease.getFencingToken()!=task.getFencingToken()||!lease.getState().equals("ACTIVE")||!lease.getExpiresAt().isAfter(store.clock.instant()))throw PcException.conflict("目录产物许可不是当前有效lease/attempt");
    }
    static final class LimitedInput extends FilterInputStream{
        long consumed;private long limit=DOCUMENT_LIMIT;private final java.security.MessageDigest digest;
        LimitedInput(InputStream input){super(input);try{digest=java.security.MessageDigest.getInstance("SHA-256");}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
        void limit(long value){limit=Math.min(DOCUMENT_LIMIT,value);}String sha256(){return HexFormat.of().formatHex(digest.digest());}
        private int capacity(int requested)throws IOException{if(consumed>=limit){if(limit==DOCUMENT_LIMIT)return 0;throw new IOException("目录字段容量超限");}return (int)Math.min(requested,limit-consumed);}
        public int read()throws IOException{if(capacity(1)==0)return -1;int value=in.read();if(value>=0){consumed++;digest.update((byte)value);}return value;}
        public int read(byte[] bytes,int offset,int length)throws IOException{int available=capacity(length);if(available==0)return -1;int value=in.read(bytes,offset,available);if(value>0){consumed+=value;digest.update(bytes,offset,value);}return value;}
        public long skip(long count)throws IOException{byte[] buffer=new byte[8192];long skipped=0;while(skipped<count){int read=read(buffer,0,(int)Math.min(buffer.length,count-skipped));if(read<0)break;skipped+=read;}return skipped;}
    }
}
